INSERT INTO LocalizedText (Language, Tag, Text) VALUES
('en_US', 'LOC_TRAIT_LEADER_AURORA_SANCTUARY_DESCRIPTION', 'Amphitheaters, Lighthouses, Shrines, Universities, Banks and Factories grants +1 corresponding yield for all unimproved Charming tiles, +2 for all unimproved Breathtaking tiles to the city they are in. {LOC_TRAIT_LEADER_AURORA_SANCTUARY_DESCRIPTION_SHARED}{LOC_TRAIT_GOURMET_EDIFICE_BONUS}'),
('en_US', 'LOC_TRAIT_CIVILIZATION_LANDSOL_KOKKORO_PRINCESS_DESCRIPTION', '{LOC_TRAIT_CIVILIZATION_LANDSOL_ALL_DESCRIPTION}{LOC_TRAIT_LEADER_AURORA_SANCTUARY_NAME}: {LOC_TRAIT_LEADER_AURORA_SANCTUARY_DESCRIPTION}'),
('zh_Hans_CN', 'LOC_TRAIT_LEADER_AURORA_SANCTUARY_DESCRIPTION', '{LOC_BUILDING_AMPHITHEATER_NAME}、灯塔、神社、大学、银行和工厂为所在城市所有迷人的未改良单元格+1相应产出，惊艳的未改良单元格则+2。{LOC_TRAIT_LEADER_AURORA_SANCTUARY_DESCRIPTION_SHARED}{LOC_TRAIT_GOURMET_EDIFICE_BONUS}'),
('zh_Hans_CN', 'LOC_TRAIT_CIVILIZATION_LANDSOL_KOKKORO_PRINCESS_DESCRIPTION', '{LOC_TRAIT_CIVILIZATION_LANDSOL_ALL_DESCRIPTION}“{LOC_TRAIT_LEADER_AURORA_SANCTUARY_NAME}”：{LOC_TRAIT_LEADER_AURORA_SANCTUARY_DESCRIPTION}'),
('ko_KR', 'LOC_TRAIT_LEADER_AURORA_SANCTUARY_DESCRIPTION', '원형극장, 등대, 성소, 대학교, 은행과 공장이 각자의 분야에 맞는 산출을, 해당 도시의 미개발된 멋진 매력도의 타일에 +1씩, 놀라운 매력도의 타일에 +2씩 부여합니다. {LOC_TRAIT_LEADER_AURORA_SANCTUARY_DESCRIPTION_SHARED}{LOC_TRAIT_GOURMET_EDIFICE_BONUS}'),
('ko_KR', 'LOC_TRAIT_CIVILIZATION_LANDSOL_KOKKORO_PRINCESS_DESCRIPTION', '{LOC_TRAIT_CIVILIZATION_LANDSOL_ALL_DESCRIPTION}{LOC_TRAIT_LEADER_AURORA_SANCTUARY_NAME}: {LOC_TRAIT_LEADER_AURORA_SANCTUARY_DESCRIPTION}');	
